import { expect, expectStatus, test } from "../../fixtures";

test("approving the replacement approves a vendor whose other documents were already approved", { tag: "@LIF-06" }, async ({ factory, apiAs }) => {
  // Arrange: a vendor in review; approve insurance and contract, reject the W-9 (vendor becomes rejected).
  const { vendor, extractions } = await factory.vendorInReview({ as: "member" });
  const reviewer = await apiAs("reviewer");
  const member = await apiAs("member");

  expectStatus(
    await reviewer.post(`/api/extractions/${extractions.insurance_certificate.id}/decision`, {
      data: { decision: "approve" },
    }),
    200,
  );
  expectStatus(
    await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, {
      data: { decision: "approve" },
    }),
    200,
  );
  expectStatus(
    await reviewer.post(`/api/extractions/${extractions.w9.id}/decision`, {
      data: { decision: "reject", note: "Legal name does not match" },
    }),
    200,
  );

  // Arrange: the member replaces the W-9, waits for extraction, and resubmits.
  const replacement = await factory.upload(vendor.id, "w9", "w9.txt", "member");
  await expect
    .poll(async () => (await factory.extraction(replacement.id, "member")).status, {
      message: "replacement W-9 extraction awaits review",
      timeout: 30_000,
    })
    .toBe("pending_review");
  const resubmitted = await expectStatus<{ status: string }>(
    await member.post(`/api/vendors/${vendor.id}/submit`),
    200,
  );
  expect(resubmitted.status).toBe("in_review");

  // Act: the reviewer approves the replacement W-9.
  const decided = await expectStatus<{ status: string }>(
    await reviewer.post(`/api/extractions/${(await factory.extraction(replacement.id, "member")).id}/decision`, {
      data: { decision: "approve" },
    }),
    200,
  );

  // Assert: the stored vendor status and audit trail reflect the approval.
  expect(decided.status).toBe("approved");
  const stored = await expectStatus<{ status: string }>(await reviewer.get(`/api/vendors/${vendor.id}`), 200);
  expect(stored.status).toBe("approved");
  const audit = await expectStatus<{ items: { action: string }[] }>(
    await reviewer.get(`/api/vendors/${vendor.id}/audit`),
    200,
  );
  expect(audit.items.map((e) => e.action)).toContain("vendor.approved");
});
